-- 46_engagement_surveys.sql — SDBI B-10b m2 import: legacy RTL engagement_* cluster -> 3 sys.* tables (S971).
-- RTL-only (legacy tenant 0c54b84a -> v5 RTL 86ba7a65). Employee-centric (I14):
--   surveys/templates author created_by = legacy users row -> bridged via users.employee_id ->
--     sys_users.user_external_code='LEGACY_EMP::'||employee_id; unresolved -> FK NULL + legacy id in *_metadata.
--   responses subject employee_id = legacy employees.id -> same LEGACY_EMP:: crosswalk.
-- 0 anonymous rows in the legacy data -> no anonymous_token path (dropped for v1).
-- Sibling pattern: 45_mentorship.sql. Data baked as VALUES (CI-reproducible). Idempotent:
--   ON CONFLICT (tenant, natural_key) DO NOTHING.
-- Expected landed (RTL): templates 5 / surveys 6 / responses 862. All 158 distinct responding
--   employees + the single survey author resolve in sys_users (0 unresolved on this RTL slice).
-- Source-vs-target: legacy cluster total = 18 surveys / 20 templates / 1327 responses across 3 tenants;
--   this seed imports the RTL slice only (mirrors 45_mentorship RTL-only scope). Non-RTL tenants
--   are out of scope here (legacy tenants 1d7bf448 + fb1e866c have no v5 tenancy mapping).
BEGIN;

-- §1 — templates (created_by NULL on all RTL rows -> NULL user)
WITH src(lid,name,descr,category,questions,is_system) AS (VALUES
  ('fa7a8843-816a-4001-af9f-2ba6c4811ede','Employee Engagement Survey','Comprehensive engagement survey covering key dimensions of employee experience','engagement','[{"id": "q1", "text": "On a scale of 0-10, how likely are you to recommend this company as a great place to work?", "type": "nps", "required": true}, {"id": "q2", "text": "I feel valued for my contributions to the team", "type": "scale_5", "required": true}, {"id": "q3", "text": "I have the resources and tools I need to do my job effectively", "type": "scale_5", "required": true}, {"id": "q4", "text": "My manager provides clear direction and support", "type": "scale_5", "required": true}, {"id": "q5", "text": "I see a clear path for career growth at this company", "type": "scale_5", "required": true}, {"id": "q6", "text": "I feel connected to the company mission and values", "type": "scale_5", "required": true}, {"id": "q7", "text": "My work-life balance is healthy", "type": "scale_5", "required": true}, {"id": "q8", "text": "What is the one thing we could do to improve your experience?", "type": "text", "required": false}]',true),
  ('04faba36-473f-4a31-83be-26b67791d7e9','Weekly Pulse Check','Quick 3-question pulse check for weekly engagement tracking','engagement','[{"id": "q1", "text": "How are you feeling about work this week?", "type": "scale_5", "labels": ["Very unhappy", "Unhappy", "Neutral", "Happy", "Very happy"], "required": true}, {"id": "q2", "text": "Do you have what you need to be productive?", "type": "scale_5", "labels": ["Strongly disagree", "Disagree", "Neutral", "Agree", "Strongly agree"], "required": true}, {"id": "q3", "text": "Any blockers or concerns to share?", "type": "text", "required": false}]',true),
  ('447015cd-73e0-4652-811f-947d386ea698','Exit Interview Survey','Standard exit interview to understand departure reasons and gather feedback','exit','[{"id": "q1", "text": "What is the primary reason for your departure?", "type": "multiple_choice", "options": ["Better opportunity elsewhere", "Compensation/benefits", "Work-life balance", "Relationship with manager", "Limited career growth", "Company culture", "Relocation", "Personal reasons", "Other"], "required": true}, {"id": "q2", "text": "How would you rate your overall experience working here?", "type": "scale_5", "required": true}, {"id": "q3", "text": "How likely are you to recommend this company to others?", "type": "nps", "required": true}, {"id": "q4", "text": "What did you enjoy most about working here?", "type": "text", "required": false}, {"id": "q5", "text": "What could we have done to keep you?", "type": "text", "required": false}, {"id": "q6", "text": "Any other feedback you would like to share?", "type": "text", "required": false}]',true),
  ('fb23b620-7c75-49f7-a0e2-bc80fec34b7e','Onboarding Check-in','30-day onboarding experience survey for new hires','onboarding','[{"id": "q1", "text": "My onboarding experience has been positive so far", "type": "scale_5", "required": true}, {"id": "q2", "text": "I understand my role and responsibilities clearly", "type": "scale_5", "required": true}, {"id": "q3", "text": "I have received adequate training to do my job", "type": "scale_5", "required": true}, {"id": "q4", "text": "My manager has been supportive during onboarding", "type": "scale_5", "required": true}, {"id": "q5", "text": "I feel welcomed by my team", "type": "scale_5", "required": true}, {"id": "q6", "text": "Based on your experience so far, how likely are you to recommend this company?", "type": "nps", "required": true}, {"id": "q7", "text": "What could we improve in our onboarding process?", "type": "text", "required": false}]',true),
  ('da9c3325-9b4a-44ab-9e9e-676a960266fe','Wellbeing Assessment','Employee wellbeing and mental health check-in','wellbeing','[{"id": "q1", "text": "I feel my workload is manageable", "type": "scale_5", "required": true}, {"id": "q2", "text": "I am able to disconnect from work during off-hours", "type": "scale_5", "required": true}, {"id": "q3", "text": "I feel supported when dealing with stress", "type": "scale_5", "required": true}, {"id": "q4", "text": "The company cares about employee wellbeing", "type": "scale_5", "required": true}, {"id": "q5", "text": "I have access to resources that support my wellbeing", "type": "scale_5", "required": true}, {"id": "q6", "text": "What additional wellbeing support would you find helpful?", "type": "text", "required": false}]',true)
)
INSERT INTO sys.sys_engagement_survey_templates
  (template_tenant_id, template_natural_key, template_name, template_description, template_category,
   template_questions, template_is_system, template_created_by_user_id, template_metadata)
SELECT '86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid, 'LEGACY_ESTMPL::'||src.lid, src.name, src.descr, src.category,
  src.questions::jsonb, src.is_system, NULL::uuid,
  jsonb_build_object('legacy_template_id', src.lid)
FROM src
ON CONFLICT (template_tenant_id, template_natural_key) DO NOTHING;

-- §2 — surveys (template via LEGACY_ESTMPL::; author via legacy users.employee_id -> LEGACY_EMP::)
WITH src(lid,template_lid,title,descr,questions,status,audience_type,audience_ids,total_invitations,total_responses,start_date,end_date,created_by_emp_lid) AS (VALUES
