  ('3e055eb0-168d-42e7-95c6-3e89c872b0ca',NULL,'Wellbeing & Work-Life Balance Survey','Sondaggio dedicato al benessere e work-life balance dei dipendenti','[{"id": "q1", "text": "Come valuti il tuo livello di stress lavorativo?", "type": "rating", "scale": 5}, {"id": "q2", "text": "Riesci a mantenere un buon equilibrio vita-lavoro?", "type": "rating", "scale": 5}, {"id": "q3", "text": "Ti senti supportato in caso di difficoltà personali?", "type": "rating", "scale": 5}, {"id": "q4", "text": "Come valuti le iniziative di welfare aziendale?", "type": "rating", "scale": 5}, {"id": "q5", "text": "Quali iniziative di wellbeing vorresti vedere?", "type": "text"}]','closed','all','{}',156,146,'2024-09-01 00:00:00+00','2024-09-15 00:00:00+00','b9960ac4-61c5-4691-b6cd-ddb76d116c17'),
  ('7be3e49d-2eea-4b27-8226-b84fdb5b005c',NULL,'Engagement Survey Q3 2024','Sondaggio trimestrale sul clima aziendale - terzo trimestre','[{"id": "q1", "text": "Quanto ti senti supportato dal team nella crescita professionale?", "type": "rating", "scale": 5}, {"id": "q2", "text": "Come valuti gli strumenti e le risorse a tua disposizione?", "type": "rating", "scale": 5}, {"id": "q3", "text": "Ti senti parte di una cultura aziendale positiva?", "type": "rating", "scale": 5}, {"id": "q4", "text": "Quanto consiglieresti la nostra azienda come posto di lavoro?", "type": "nps", "scale": 10}, {"id": "q5", "text": "Come possiamo migliorare la collaborazione tra team?", "type": "text"}]','closed','all','{}',156,144,'2024-07-15 00:00:00+00','2024-07-31 00:00:00+00','b9960ac4-61c5-4691-b6cd-ddb76d116c17'),
  ('bd63ab94-37ee-45ef-b906-8e406d48bbfb',NULL,'Engagement Survey Q2 2024','Sondaggio trimestrale sul clima aziendale - secondo trimestre','[{"id": "q1", "text": "Come valuti il work-life balance nella tua posizione?", "type": "rating", "scale": 5}, {"id": "q2", "text": "Ti senti adeguatamente riconosciuto per il tuo contributo?", "type": "rating", "scale": 5}, {"id": "q3", "text": "Quanto chiari sono gli obiettivi del tuo team?", "type": "rating", "scale": 5}, {"id": "q4", "text": "Quanto consiglieresti la nostra azienda come posto di lavoro?", "type": "nps", "scale": 10}, {"id": "q5", "text": "Quali iniziative vorresti vedere implementate?", "type": "text"}]','closed','all','{}',156,147,'2024-04-15 00:00:00+00','2024-04-30 00:00:00+00','b9960ac4-61c5-4691-b6cd-ddb76d116c17'),
