INSERT INTO sys.sys_engagement_surveys
  (survey_tenant_id, survey_natural_key, survey_template_id, survey_title, survey_description, survey_questions,
   survey_status, survey_audience_type, survey_audience_ids, survey_is_anonymous, survey_total_invitations,
   survey_total_responses, survey_created_by_user_id, survey_start_date, survey_end_date, survey_metadata)
SELECT '86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid, 'LEGACY_ESURV::'||src.lid, t.template_id, src.title, src.descr,
  src.questions::jsonb, src.status, src.audience_type, src.audience_ids::uuid[], false,
  src.total_invitations::int, src.total_responses::int, author.user_id, src.start_date::timestamptz, src.end_date::timestamptz,
  jsonb_strip_nulls(jsonb_build_object('legacy_survey_id', src.lid,
    'unresolved_author_employee', CASE WHEN author.user_id IS NULL THEN src.created_by_emp_lid END,
    'legacy_template_id', CASE WHEN t.template_id IS NULL THEN src.template_lid END))
FROM src
LEFT JOIN sys.sys_engagement_survey_templates t ON t.template_natural_key='LEGACY_ESTMPL::'||src.template_lid AND t.template_tenant_id='86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid
LEFT JOIN sys.sys_users author ON author.user_external_code='LEGACY_EMP::'||src.created_by_emp_lid
ON CONFLICT (survey_tenant_id, survey_natural_key) DO NOTHING;

