INSERT INTO sys.sys_engagement_survey_responses
  (response_tenant_id, response_natural_key, response_survey_id, response_subject_user_id, response_answers,
   response_is_complete, response_started_at, response_completed_at, response_metadata)
SELECT '86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid, 'LEGACY_ESRESP::'||src.lid, s.survey_id, subj.user_id, src.answers::jsonb,
  src.is_complete, src.started_at::timestamptz, src.completed_at::timestamptz,
  jsonb_strip_nulls(jsonb_build_object('legacy_response_id', src.lid, 'legacy_employee_id', src.subject_emp_lid,
    'unresolved_subject', CASE WHEN subj.user_id IS NULL THEN src.subject_emp_lid END))
FROM src
JOIN sys.sys_engagement_surveys s ON s.survey_natural_key='LEGACY_ESURV::'||src.survey_lid AND s.survey_tenant_id='86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid
LEFT JOIN sys.sys_users subj ON subj.user_external_code='LEGACY_EMP::'||src.subject_emp_lid
ON CONFLICT (response_tenant_id, response_natural_key) DO NOTHING;

-- §4 — reconciliation registry (classify the 3 new tables; status POPULATED resolves live via has_rows)
INSERT INTO sys.sys_reconciliation_registry
  (reconciliation_registry_table_name, reconciliation_registry_bucket, reconciliation_registry_declared_status,
   reconciliation_registry_legacy_source, reconciliation_registry_legacy_source_rows, reconciliation_registry_rationale)
VALUES
  ('sys_engagement_survey_templates','A','IMPORT','engagement_survey_templates',20,'[S971 SDBI m2] Reusable survey templates; RTL-only import (5 of 20 legacy rows).'),
  ('sys_engagement_surveys','A','IMPORT','engagement_surveys',18,'[S971 SDBI m2] Survey definitions; RTL-only (6 of 18); employee-centric author via users.employee_id LEGACY_EMP.'),
  ('sys_engagement_survey_responses','A','IMPORT','engagement_survey_responses',1327,'[S971 SDBI m2] Immutable response event log; RTL-only (862 of 1327); subject via LEGACY_EMP crosswalk; CASCADE child of surveys.')
ON CONFLICT (reconciliation_registry_table_name) DO NOTHING;

DO $post$
DECLARE t int; s int; r int; u int;
BEGIN
  SELECT count(*) INTO t FROM sys.sys_engagement_survey_templates;
  SELECT count(*) INTO s FROM sys.sys_engagement_surveys;
  SELECT count(*) INTO r FROM sys.sys_engagement_survey_responses;
  SELECT count(*) INTO u FROM sys.sys_engagement_survey_responses WHERE response_subject_user_id IS NULL;
  RAISE NOTICE '46_engagement_surveys: templates=% surveys=% responses=% (expect 5/6/862); unresolved subjects=% (expect 0)', t, s, r, u;
  IF t<>5 OR s<>6 OR r<>862 THEN
    RAISE EXCEPTION '46_engagement_surveys: count mismatch t=% s=% r=%', t, s, r;
  END IF;
END $post$;
COMMIT;
